SELECT p.status, COUNT(DISTINCT p.id) AS n, SUM(p.realized_pnl < 0) AS losers, ROUND(SUM(p.realized_pnl),4) AS pnl_gross, SUM(w.take_profit_usdt > s.take_profit) AS tp_extended_n FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id = p.signal_id JOIN crypto_ai.wallet_managed_position w ON w.entry_signal_id = p.signal_id WHERE p.closed_at IS NOT NULL AND w.highest_price_usdt >= s.take_profit GROUP BY p.status LIMIT 10;